#!/usr/bin/env node
/* MVP Trainer Pro R10.1 - DSP UI Refinement
   Surgical UI-only installer. Replaces only src/features/music/MusicMiniPlayer.tsx.
*/
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const EXPECTED_SHA = "5633a49e3734cad4d80563d6cc87a53010033aed6dc9865f9b9186802e72eb1a";
const PAYLOAD_B64 = "";
const TARGET_REL = path.join("src", "features", "music", "MusicMiniPlayer.tsx");

function sha256(buffer) { return crypto.createHash("sha256").update(buffer).digest("hex"); }
function findRepoRoot(start) {
  let dir = path.resolve(start);
  for (let i = 0; i < 8; i++) {
    if (fs.existsSync(path.join(dir, "package.json")) && fs.existsSync(path.join(dir, "src"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error("Could not locate MVP Trainer repo root. Run this installer from the repo or its scripts folder.");
}

const here = path.dirname(fileURLToPath(import.meta.url));
const root = findRepoRoot(process.cwd() === here ? here : process.cwd());
const target = path.join(root, TARGET_REL);
const payload = Buffer.from(PAYLOAD_B64, "base64");
if (sha256(payload) !== EXPECTED_SHA) throw new Error("Embedded payload checksum failed.");
if (!fs.existsSync(target)) throw new Error(`Missing target file: ${target}`);

const current = fs.readFileSync(target);
if (sha256(current) === EXPECTED_SHA) {
  console.log("R10.1 DSP UI Refinement is already installed.");
  process.exit(0);
}

const backupDir = path.join(root, ".mvp-backups", "r10-1-dsp-ui-refinement");
fs.mkdirSync(backupDir, { recursive: true });
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backup = path.join(backupDir, `MusicMiniPlayer.tsx.${stamp}.bak`);
fs.copyFileSync(target, backup);
fs.writeFileSync(target, payload);

const installed = fs.readFileSync(target);
if (sha256(installed) !== EXPECTED_SHA) {
  fs.copyFileSync(backup, target);
  throw new Error("Verification failed after install. Original file restored.");
}

console.log("Installed MVP Trainer Pro R10.1 DSP UI Refinement.");
console.log(`Updated: ${TARGET_REL}`);
console.log(`Backup: ${path.relative(root, backup)}`);
console.log("DSP/WASM/audio engine files were not modified.");
